#!/usr/bin/env python3
"""Generate `.ci-history/runs.json` for the fixture suite.

Deterministic: no wall-clock, no randomness. The scripted failures encode the
stories the fixture suite exercises:

* flaky tests fail on a fixed cadence (≥3 pass/fail transitions over 24 runs);
* zombie tests (import of a deleted symbol) fail in every run;
* three organic tests have historical failures — real regressions they caught
  (files_changed names the regressing production file);
* `tests/test_brittle.py` is re-baselined in several runs — snapshot churn,
  the §5 signal that weights brittleness upward.

Run:  python3 src/tests/fixtures/tools/make_ci_history.py
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

FIXTURES = Path(__file__).resolve().parent.parent
RUNS = 24

FLAKY = {
    "tests/test_flaky.py::test_flaky_timeouts": lambda i: i % 3 == 1,
    "tests/test_flaky.py::test_flaky_race": lambda i: i % 5 == 2,
    "tests/test_flaky.py::test_flaky_retry": lambda i: i % 4 == 3,
}

ALWAYS_FAILING = {
    "tests/test_zombie.py::test_zombie_removed_helper",
    "tests/test_zombie.py::test_zombie_missing_class",
}

# Historical regressions caught by organic tests: test -> (run block, file).
# A real regression fails a CONTIGUOUS block of runs — the bug is present
# until it is fixed — which the flaky detector distinguishes from
# interleaved flakiness.
REGRESSIONS = {
    "tests/test_good_organic.py::test_add_two_numbers": ([6, 7, 8], "prod/calc.py"),
    "tests/test_good_organic.py::test_divide_by_zero_raises": ([10, 11], "prod/calc.py"),
    "tests/test_good_organic.py::test_price_order_discount": ([18, 19],
         "prod/pricing.py"),
}

CHURN_FILES = {
    "tests/test_brittle.py": {2, 5, 9, 14, 18, 21},
    "prod/pricing.py": {18},
}

ROUTINE_CHANGES = ["prod/reporting.py", "prod/notifier.py", "prod/warehouse.py",
                   "prod/calc.py"]


def collect_test_ids() -> list[str]:
    ids: list[str] = []
    for path in sorted((FIXTURES / "tests").glob("test_*.py")):
        text = path.read_text(encoding="utf-8")
        rel = f"tests/{path.name}"
        for m in re.finditer(r"^def (test_\w+)\(", text, re.M):
            ids.append(f"{rel}::{m.group(1)}")
    return ids


def main() -> int:
    ids = collect_test_ids()
    if not ids:
        print("no fixture tests found", file=sys.stderr)
        return 1
    runs = []
    for index in range(RUNS):
        run_id = f"r{index + 1:03d}"
        results = []
        for test_id in ids:
            if test_id in ALWAYS_FAILING:
                status = "failed"
            elif test_id in FLAKY and FLAKY[test_id](index):
                status = "failed"
            elif test_id in REGRESSIONS and (index + 1) in REGRESSIONS[test_id][0]:
                status = "failed"
            else:
                status = "passed"
            results.append({"test_id": test_id, "status": status})
        regressed_files = sorted({
            file for test, (_runs, file) in REGRESSIONS.items()
            if (index + 1) in _runs
        })
        files_changed = sorted({
            f for f, runs_with in CHURN_FILES.items() if index + 1 in runs_with
        }) or regressed_files or sorted(
            {ROUTINE_CHANGES[index % len(ROUTINE_CHANGES)]})
        runs.append({
            "run_id": run_id,
            "status": "failed" if any(
                r["status"] == "failed" for r in results) else "passed",
            "test_results": results,
            "files_changed": files_changed,
        })
    doc = {
        "provider": "local",
        "comment": "Fixture CI history generated by tools/make_ci_history.py; "
                   "provider=local (§2 CI providers).",
        "runs": runs,
    }
    out = FIXTURES / ".ci-history"
    out.mkdir(exist_ok=True)
    (out / "runs.json").write_text(
        json.dumps(doc, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"wrote {out / 'runs.json'}: {RUNS} runs, "
          f"{len(ids)} tests per run")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
